  "sim.egg-incubator.title": "Incubatrice per uova",
  "sim.egg-incubator.desc": "Gestisci temperatura, umidità e rotazione delle uova in un’incubatrice per massimizzare il tasso di schiusa.",
  "sim.dairy-farm.title": "Allevamento di latticini",
  "sim.dairy-farm.desc": "Gestisci una piccola attività di allevamento di latticini: programmi di alimentazione, cicli di mungitura e salute del gregge per massimizzare la resa.",
  "sim.poultry-farm.title": "Allevamento di pollame",
  "sim.poultry-farm.desc": "Gestisci un allevamento commerciale di pollame: alimentazione, salute e obiettivi di produzione per greggi da broiler e ovaiole.",
  "sim.cattle-dairy.title": "Bovini e latticini",
  "sim.cattle-dairy.desc": "Supervisiona un ranch di bovini e una unità di latticini, bilanciando gestione dei pascoli, allevamento e produzione di latte.",
  "sim.sheep-farm.title": "Allevamento di pecore",
  "sim.sheep-farm.desc": "Gestisci un allevamento di pecore attraverso cicli stagionali: parto degli agnelli, tosatura e vendite sul mercato.",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "Agisci come ingegnere del Network Operations Centre — diagnostica e risolvi incidenti infrastrutturali in tempo reale sotto pressione.",
  "sim.mobile-repair.title": "Laboratorio di Riparazione Mobile",
  "sim.mobile-repair.desc": "Diagnostica e ripara smartphone: sostituzioni dello schermo, problemi della batteria e guasti della scheda madre.",
  "sim.laptop-repair.title": "Laboratorio di Riparazione Laptop",
  "sim.laptop-repair.desc": "Troubleshoot e ripara laptop: guasti hardware, problemi del BIOS e sostituzioni dei componenti.",
  "sim.perfume-lab.title": "Laboratorio Profumi",
  "sim.perfume-lab.desc": "Mescola oli essenziali e composti aromatici per creare fragranze distintive e raggiungere gli standard di qualità.",
  "sim.detergent-lab.title": "Laboratorio di Detergenti",
  "sim.detergent-lab.desc": "Formula prodotti per la pulizia — bilancia tensioattivi, riempitivi e test di performance entro il budget.",
  "sim.skin-care-lab.title": "Laboratorio di Skin Care",
  "sim.skin-care-lab.desc": "Sviluppa e testa formulazioni cosmetiche, rispettando gli standard di sicurezza e gli obiettivi di efficacia.",
  "sim.woodworking.title": "Laboratorio di Falegnameria",
  "sim.woodworking.desc": "Gestisci un laboratorio di falegnameria su misura: pianifica i lavori, gestisci i materiali e consegna mobili in tempo e nei costi previsti.",
  "sim.aluminum-glazing.title": "Alluminio e Vetrate",
  "sim.aluminum-glazing.desc": "Gestisci un’attività di lavorazione dell’alluminio e installazione di vetro dalla stima al completamento in cantiere.",
  "sim.global-kitchen.title": "Cucina Globale",
  "sim.global-kitchen.desc": "Guida una cucina di ristorante: gestisci menu, personale, costi e soddisfazione dei clienti durante i turni di servizio.",
  "sim.chocolate-factory.title": "Fabbrica di Cioccolato",
  "sim.chocolate-factory.desc": "Gestisci una fabbrica di pasticceria — approvvigionamento del cacao, pianificazione della produzione e controllo qualità.",
  "sim.solar-energy.title": "Impianto di Energia Solare",
  "sim.solar-energy.desc": "Progetta e gestisci un impianto solare — dimensiona i pannelli, gestisci l’esportazione in rete e monitora il ROI.",
  "sim.hvac-systems.title": "Sistemi HVAC",
  "sim.hvac-systems.desc": "Installa e mantieni sistemi di riscaldamento, ventilazione e aria condizionata per edifici commerciali.",
  "sim.logistics-supply.title": "Logistica e Supply Chain",
  "sim.logistics-supply.desc": "Ottimizza le operazioni del magazzino, la pianificazione dei veicoli e le relazioni con i fornitori per raggiungere i KPI di consegna.",
  "sim.barber-salon.title": "Salone da Barbiere",
  "sim.barber-salon.desc": "Gestisci un barbiere: appuntamenti, turni del personale, prezzi e strategie di fidelizzazione dei clienti.",
  "sim.board-surgeon.title": "Chirurgo del Cervello",
  "sim.board-surgeon.desc": "Prendi decisioni chirurgiche ad alto rischio in una sala operatoria simulata — gestione del tempo e sicurezza del paziente.",
  "sim.english-journey.title": "Percorso di Inglese",
  "sim.english-journey.desc": "Guida gli studenti attraverso un programma strutturato di lingua inglese, adattandolo a diversi livelli di competenza.",
  "sim.music-training.title": "Studio di Formazione Musicale",
  "sim.music-training.desc": "Gestisci una scuola di musica: pianifica le lezioni, gestisci gli strumenti e monitora i progressi degli studenti verso i saggi.",
  "sim.trade-tycoon.title": "Tycoon del Commercio",
  "sim.trade-tycoon.desc": "Costruisci un impero del trading — compra a basso, vendi ad alto, gestisci inventario e flussi di cassa su più mercati.",
  "sim.vehicle-diagnostics.title": "Simulatore di Diagnostica e Riparazione del Veicolo",
  "sim.vehicle-diagnostics.desc": "Diagnostica i codici di guasto OBD-II, individua guasti elettrici e gestisci un flusso di lavoro di riparazione auto nel mondo reale.",
  "sim.marine-vessel.title": "Tracciamento delle Navi e Logistica Marittima",
  "sim.marine-vessel.desc": "Guida una flotta globale — traccia le navi, gestisci la congestione dei porti, emergenze meteo e ritardi nei canali.",
