  "jungle.howTo.1": "Sei bloccato nella giungla — scegli come sopravvivere",
  "jungle.howTo.2": "Ogni scelta influenza HP e punteggio in modo diverso",
  "jungle.howTo.3": "Se i tuoi HP arrivano a 0, la partita finisce",
  "jungle.howTo.4": "Sopravvivi a tutti gli 8 scenari per vincere!",
  "jungle.scene6": "Trovi un uccellino ferito. Cosa fai?",
  "jungle.s6c1": "Trasportalo con attenzione — potrebbe indicarti un percorso (+5 HP, +25 pts)",
  "jungle.s6c2": "Lascia stare — prendersene cura ti fa sprecare energie (0 HP, +10 pts)",
  "jungle.scene7": "Un fiume blocca la tua strada. L’acqua sembra veloce.",
  "jungle.s7c1": "Costruisci una zattera con i tronchi caduti (−5 HP, +40 pts)",
  "jungle.s7c2": "Vai a monte per trovare un guado poco profondo (+10 HP, +20 pts)",
  "jungle.scene8": "Vedi del fumo in lontananza.",
  "jungle.s8c1": "Vai verso il fumo — potrebbe essere un salvataggio! (+15 HP, +45 pts)",
  "jungle.s8c2": "Stane alla larga — potrebbe esserci un incendio (−5 HP, +15 pts)",
  "jungle.scene9": "Cala la notte. Ti serve un riparo.",
  "jungle.s9c1": "Sali su un albero alto per restare al sicuro dai predatori (+10 HP, +30 pts)",
  "jungle.s9c2": "Costruisci un riparo a terra con dei rami (−5 HP, +35 pts)",
  "jungle.scene10": "Trovi un frutto che non riconosci. Hai davvero molta fame.",
  "jungle.s10c1": "Mangialo — sei allo stremo! (−20 HP, +30 pts)",
  "jungle.s10c2": "Prova prima un pezzettino sulla pelle (0 HP, +20 pts)",
  "jungle.scene11": "Sul sentiero c’è un serpente grande che si avvolge.",
  "jungle.s11c1": "Fatti indietro lentamente e trova un percorso alternativo (+5 HP, +30 pts)",
  "jungle.s11c2": "Prova a spaventarlo (−25 HP, +40 pts)",
  "jungle.scene12": "Senti una cascata — le tue scorte d’acqua sono ormai critiche.",
  "jungle.s12c1": "Segui il suono per trovare acqua fresca (+20 HP, +35 pts)",
  "jungle.s12c2": "Ignoralo e continua ad andare avanti (−15 HP, +20 pts)",
  "jungle.scene13": "Una tempesta si sta avvicinando rapidamente.",
  "jungle.s13c1": "Cerca terreno elevato e riparo (+10 HP, +25 pts)",
  "jungle.s13c2": "Continua a muoverti per scappare (−10 HP, +30 pts)",
  "jungle.scene14": "Trovi una grotta. Sta diventando buio.",
  "jungle.s14c1": "Entra nella grotta per ripararti (+15 HP, +30 pts)",
  "jungle.s14c2": "Dormi sotto un albero — la grotta potrebbe essere occupata (+5 HP, +20 pts)",
  "jungle.scene15": "Sei esausto. Una radura davanti sembra sicura.",
  "jungle.s15c1": "Riposa e recupera (+20 HP, +20 pts)",
  "jungle.s15c2": "Vai avanti — qui riposare è pericoloso (−5 HP, +30 pts)",
  "jungle.scene16": "Trovi una vecchia mappa incisa su un albero.",
  "jungle.s16c1": "Segui la direzione della mappa (+5 HP, +40 pts)",
  "jungle.s16c2": "Ignorala — potrebbe essere vecchia (0 HP, +10 pts)",
  "jungle.scene17": "I cinghiali attraversano la tua strada in modo aggressivo.",
  "jungle.s17c1": "Sali subito sull’albero più vicino (+5 HP, +30 pts)",
  "jungle.s17c2": "Tieniti fermo e urla (−20 HP, +35 pts)",
  "jungle.scene18": "Trovi un campo abbandonato pieno di provviste.",
  "jungle.s18c1": "Prendi tutto ciò che è utile (+20 HP, +50 pts)",
  "jungle.s18c2": "Lascia stare — potrebbe servirne a qualcuno dopo (0 HP, +10 pts)",
  "jungle.scene19": "Un simio ruba la tua borsa del cibo!",
  "jungle.s19c1": "Insegui il simio (−10 HP, +40 pts)",
  "jungle.s19c2": "Lascia perdere — non vale le energie (+0 HP, +15 pts)",
  "jungle.scene20": "Senti un elicottero sopra di te.",
  "jungle.s20c1": "Accendi subito un fuoco di segnalazione! (+30 HP, +60 pts)",
  "jungle.s20c2": "Agita le braccia — potrebbe vederti (+5 HP, +40 pts)",
